"""Reusable, self-contained recipe detail page for Oui, Chef."""
import html
import re


def suggested_minutes(step: str) -> int | None:
    hour = re.search(r"\b(\d+)(?:½)?\s*(?:[–-]\s*(\d+))?\s*hours?\b", step, re.I)
    if hour:
        return int(hour.group(2) or hour.group(1)) * 60
    match = re.search(r"\b(\d+)\s*(?:[–-]\s*(\d+))?\s*(?:minutes?|mins?)\b", step, re.I)
    return int(match.group(2) or match.group(1)) if match else None


def render_recipe_page(meal: dict) -> bytes:
    recipe = meal.get("recipe", {})
    name = html.escape(str(meal.get("name", "Recipe")))
    summary = html.escape(str(recipe.get("summary") or meal.get("description", meal.get("nutrition_note", ""))))
    image = str(recipe.get("image_url", ""))
    fallback = '<div class="hero-image placeholder" role="img" aria-label="Recipe without a photo"><svg width="64" height="64" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.2" aria-hidden="true"><path d="M4 3v6a3 3 0 0 0 6 0V3M7 3v19M20 22V3c-4 3-4 9 0 9"/></svg></div>'
    image_html = (f'<img class="hero-image" src="{html.escape(image, quote=True)}" alt="{name}" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><div hidden>{fallback}</div>' if image.startswith(('https://', 'http://')) else fallback)
    ingredients = recipe.get("ingredients", []) or meal.get("ingredients", [])
    def ingredient_text(item):
        if isinstance(item, str):
            return item
        return f"{item.get('quantity', '')} {item.get('unit', '')} {item.get('name', '')}".strip()
    ingredient_html = "".join(f"<li>{html.escape(ingredient_text(item))}</li>" for item in ingredients)
    steps = recipe.get("steps", meal.get("method", []))
    def render_step(i, step):
        minutes = suggested_minutes(str(step))
        timer = ""
        if minutes is not None:
            timer = f'''<div class="timer" data-timer="step-{i}"><label>Timer <input aria-label="Minutes for step {i}" class="minutes" type="number" min="1" max="240" value="{minutes}"> min</label><strong class="clock">{minutes:02d}:00</strong><div class="timer-actions"><button class="start">Start</button><button class="pause" disabled>Pause</button><button class="plain reset">Reset</button><button class="plain cancel">Cancel</button></div></div>'''
        return f'''<article class="step-card"><div class="step-number">{i}</div><div class="step-copy"><span>Step {i}</span><p>{html.escape(str(step))}</p><div class="step-actions"><button class="complete-step" aria-pressed="false">○ Mark complete</button><button class="toggle-step" aria-expanded="true">Hide step details</button></div>{timer}</div></article>'''
    step_html = "".join(render_step(i, step) for i, step in enumerate(steps, 1)) or '<p class="empty">No method has been saved for this recipe yet.</p>'
    metadata = []
    complexity = recipe.get("complexity") or meal.get("complexity")
    if complexity:
        metadata.append(f"<span class=\"pill\">{html.escape(str(complexity))}</span>")
    for key, label in (("prep_time_min", "prep"), ("cook_time_min", "cook")):
        value = recipe.get(key)
        if isinstance(value, int) and 0 < value <= 480:
            metadata.append(f"<span class=\"pill\">{value} min {label}</span>")
    health = recipe.get("health_rating")
    if isinstance(health, int) and 1 <= health <= 5:
        metadata.append(f"<span class=\"pill health\">Health fit {health}/5</span>")
    metadata_html = f'<div class="pills">{"".join(metadata)}</div>' if metadata else ""
    source = str(meal.get("url", ""))
    source_html = f'<a class="source" href="{html.escape(source, quote=True)}" target="_blank" rel="noopener">Original source ↗</a>' if source.startswith(("https://", "http://")) else ""
    page = f'''<!doctype html><html lang="en-AU"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{name} · Oui, Chef</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:opsz,wght@9..40,400;9..40,500;9..40,600;9..40,700&display=swap" rel="stylesheet"><style>:root{{--ink:#233027;--muted:#6d786f;--cream:#faf8f2;--surface:#fffefa;--line:#e8e5da;--olive:#314c38;--olive-soft:#e8efe5;--paprika:#d85f3f;--sun:#f3b63f;--shadow:0 1px 1px #15241508,0 8px 24px #1524150d}}[hidden]{{display:none!important}}:focus-visible{{outline:3px solid var(--paprika);outline-offset:3px}}@media(prefers-reduced-motion:reduce){{*{{animation:none!important;transition:none!important}}}}*{{box-sizing:border-box}}body{{margin:0;background:var(--cream);color:var(--ink);font:16px 'DM Sans',system-ui,sans-serif}}.recipe-app{{max-width:740px;margin:auto;padding:18px 16px 52px}}.back{{display:inline-block;color:var(--olive);font-size:14px;font-weight:700;text-decoration:none;margin:3px 0 18px}}.hero{{overflow:hidden;background:var(--surface);border:1px solid var(--line);border-radius:25px;box-shadow:var(--shadow)}}.hero-image{{display:block;width:100%;height:250px;object-fit:cover;background:linear-gradient(135deg,#e6ecdF,#f5d8ba)}}.placeholder{{display:grid;place-items:center;font-size:50px;color:var(--paprika)}}.hero-copy{{padding:22px}}.eyebrow{{text-transform:uppercase;letter-spacing:.12em;font-size:11px;font-weight:700;color:var(--paprika);margin:0 0 7px}}h1{{font-size:31px;line-height:1.05;letter-spacing:-.045em;margin:0}}.pills{{display:flex;flex-wrap:wrap;gap:7px;margin:14px 0 2px}}.pill{{display:inline-flex;align-items:center;border-radius:999px;padding:6px 10px;background:#edf2e8;color:var(--olive);font-size:12px;font-weight:700}}.pill.health{{background:#fff1de;color:#94531e}}.summary{{color:var(--muted);line-height:1.45;margin:10px 0 16px}}.source{{font-size:13px;font-weight:700;color:var(--olive)}}.section{{margin-top:25px}}h2{{font-size:21px;letter-spacing:-.03em;margin:0 0 11px}}.ingredients{{columns:2;gap:18px;background:var(--surface);border:1px solid var(--line);border-radius:19px;margin:0;padding:18px 18px 18px 35px;line-height:1.6;font-size:14px}}.step-card{{position:relative;display:flex;gap:13px;background:var(--surface);border:1px solid var(--line);border-radius:19px;padding:17px;margin:11px 0;box-shadow:var(--shadow)}}.step-number{{display:grid;place-items:center;flex:none;width:27px;height:27px;border-radius:9px;background:var(--olive);color:#fff;font-size:13px;font-weight:700}}.step-copy{{min-width:0;flex:1}}.step-copy>span{{font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--paprika)}}.step-copy p{{line-height:1.48;margin:5px 0 14px}}.step-actions{{display:flex;gap:7px;flex-wrap:wrap;margin:0 0 13px}}.complete-step,.toggle-step{{background:#f3f1ea;color:var(--olive)}}.step-card.complete{{background:#f3f8ef;border-color:#bad0b6}}.step-card.complete .step-number{{background:#6f9a68}}.step-card.minimised .step-copy>p,.step-card.minimised .timer{{display:none}}.step-card.minimised .step-actions{{margin:4px 0 0}}.timer{{display:grid;grid-template-columns:auto 1fr;gap:9px;align-items:center;border-top:1px solid var(--line);padding-top:13px}}.timer label{{font-size:12px;font-weight:700;color:var(--muted)}}.minutes{{width:44px;border:1px solid var(--line);border-radius:8px;padding:6px;font:inherit;text-align:center;color:var(--ink)}}.clock{{font-variant-numeric:tabular-nums;font-size:22px;letter-spacing:-.05em}}button{{border:0;cursor:pointer;font:inherit;font-size:12px;font-weight:700;border-radius:9px;padding:8px 10px;background:var(--paprika);color:#fff}}button:disabled{{opacity:.45;cursor:not-allowed}}.timer-actions{{grid-column:1/-1;display:flex;gap:7px;flex-wrap:wrap}}.plain{{background:#f3f1ea;color:var(--olive)}}.timer.done .clock{{color:#bd4d30}}.timer.done{{animation:pulse 1s ease-in-out infinite}}@keyframes pulse{{50%{{background:#fff1e9}}}}.empty{{color:var(--muted)}}@media(max-width:520px){{.recipe-app{{padding:12px 12px 36px}}.hero-image{{height:205px}}h1{{font-size:27px}}.ingredients{{columns:1}}.timer{{grid-template-columns:auto 1fr}}}}</style><body><main class="recipe-app"><a class="back" href="/">← Back to Oui, Chef</a><section class="hero">{image_html}<div class="hero-copy"><p class="eyebrow">Cook mode</p><h1>{name}</h1>{metadata_html}<p class="summary">{summary}</p>{source_html}</div></section><section class="section"><h2>Ingredients</h2><ul class="ingredients">{ingredient_html}</ul></section><section class="section"><h2>Step by step</h2><p class="summary">Start as many timers as you need. Timers continue independently while this page stays open.</p>{step_html}</section></main><script>const states=new Map();let audio;function beep(){{try{{audio??=new AudioContext();let t=audio.currentTime;[0,.22,.44].forEach(x=>{{let o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=880;g.gain.setValueAtTime(.0001,t+x);g.gain.exponentialRampToValueAtTime(.14,t+x+.02);g.gain.exponentialRampToValueAtTime(.0001,t+x+.16);o.start(t+x);o.stop(t+x+.18)}})}}catch(e){{}}}}function display(node,s){{node.querySelector('.clock').textContent=Math.floor(s/60).toString().padStart(2,'0')+':'+(s%60).toString().padStart(2,'0')}}function initial(node){{return Math.max(1,+node.querySelector('.minutes').value||1)*60}}function stop(state){{if(state.interval)clearInterval(state.interval);if(state.alarm)clearInterval(state.alarm);state.interval=null;state.alarm=null}}function setButtons(node,running){{node.querySelector('.start').disabled=running;node.querySelector('.pause').disabled=!running;node.querySelector('.pause').textContent='Pause'}}document.querySelectorAll('.timer').forEach(node=>{{let state={{remaining:initial(node),interval:null}};states.set(node.dataset.timer,state);display(node,state.remaining);node.querySelector('.minutes').onchange=()=>{{if(!state.interval){{state.remaining=initial(node);display(node,state.remaining)}}}};node.querySelector('.start').onclick=()=>{{if(state.remaining<1)state.remaining=initial(node);audio??=new AudioContext();audio.resume?.();state.interval=setInterval(()=>{{state.remaining--;display(node,state.remaining);if(state.remaining<=0){{stop(state);node.classList.add('done');setButtons(node,false);node.querySelector('.pause').disabled=false;beep();state.alarm=setInterval(beep,2500);if(navigator.vibrate)navigator.vibrate([180,80,180,80,180])}}}},1000);node.classList.remove('done');setButtons(node,true)}};node.querySelector('.pause').onclick=()=>{{if(state.interval||state.alarm){{stop(state);node.querySelector('.start').disabled=false;node.querySelector('.pause').textContent='Paused'}}}};node.querySelector('.reset').onclick=()=>{{stop(state);state.remaining=initial(node);node.classList.remove('done');display(node,state.remaining);setButtons(node,false)}};node.querySelector('.cancel').onclick=()=>{{stop(state);state.remaining=0;node.classList.remove('done');display(node,0);setButtons(node,false)}}}});document.querySelectorAll('.complete-step').forEach(button=>{{button.onclick=()=>{{const card=button.closest('.step-card'),done=card.classList.toggle('complete');card.classList.toggle('minimised',done);button.setAttribute('aria-pressed',String(done));button.textContent=done?'✓ Completed':'○ Mark complete';const toggle=card.querySelector('.toggle-step');toggle.textContent=done?'Show step details':'Hide step details';toggle.setAttribute('aria-expanded',String(!done))}}}});document.querySelectorAll('.toggle-step').forEach(button=>{{button.onclick=()=>{{const card=button.closest('.step-card'),expanded=card.classList.toggle('minimised');button.textContent=expanded?'Show step details':'Hide step details';button.setAttribute('aria-expanded',String(!expanded))}}}});</script></body></html>'''
    return page.encode()
